import { Diagnostic, path } from '@servicenow/sdk-build-core'
import { Project } from '../../src'
import fs from 'node:fs/promises'

describe('Tagged template literals tests', () => {
    test('no diagnostics should occur because of tagged template literals', async () => {
        const project = new Project({
            packageJson: { name: 'test', version: '1.0.0' },
            config: { scope: 'x_test', scopeId: '12345' },
        })

        project.registerExplicitId('test_table', 'test', '12345')
        const index = project.addFile({
            path: 'src/fluent/index.now.ts',
            content: `import { Record } from '@servicenow/sdk/core'

Record({
    table: 'test',
    $id: '1a8169a294de42f4b26920ce309c1bb6',
    data: {
        html_test: html\`<div>test</div>\`,
        script_test: script\`console.log("test")\`,
    },
})`,
        })

        const diagnostics = await index.getDiagnostics()
        expect(diagnostics.some((d) => d.level === Diagnostic.Level.Error)).toBeFalsy()

        const records = await index.getRecords()
        expect(records.query()).toHaveLength(1)
    })

    test('preserve tagged template literals on update', async () => {
        const project = new Project({
            packageJson: { name: 'test', version: '1.0.0' },
            config: { scope: 'x_test', scopeId: '12345' },
        })
        project.registerExplicitId('test_table', 'test', '12345')

        const index = project.addFile({
            path: 'src/fluent/index.now.ts',
            content: `import { Record } from '@servicenow/sdk/core'

Record({
  table: 'test',
  $id: '1a8169a294de42f4b26920ce309c1bb6',
  data: {
      html_test: html\`<div>test</div>\`,
  },
})`,
        })

        const diagnostics = await index.getDiagnostics()
        expect(diagnostics.some((d) => d.level === Diagnostic.Level.Error)).toBeFalsy()

        await project.transform({
            path: 'changes.xml',
            content: `<?xml version="1.0"?>
<record_update>
  <test action="INSERT_OR_UPDATE">
    <sys_id>1a8169a294de42f4b26920ce309c1bb6</sys_id>
    <sys_scope display_value="x_test">x_test01234567890123456789012345</sys_scope>
    <html_test>&lt;span&gt;test2&lt;/span&gt;</html_test>
  </test>
</record_update>`,
        })

        const fluentScript = index.getContent()
        expect(fluentScript).toBe(`import { Record } from '@servicenow/sdk/core'

Record({
    table: 'test',
    $id: '1a8169a294de42f4b26920ce309c1bb6',
    data: {
        html_test: html\`<span>test2</span>\`,
    },
})
`)

        const records = await index.getRecords()
        expect(records.query()).toHaveLength(1)

        const record = records.get('test', '1a8169a294de42f4b26920ce309c1bb6')
        expect(record).toBeDefined()

        expect(record.get('html_test').getValue()).toBe('<span>test2</span>')
    })

    test('escapes tagged literal ticks, backslashes, and dollar signs', async () => {
        const project = new Project({
            packageJson: { name: 'test', version: '1.0.0' },
            config: { scope: 'x_test', scopeId: '12345' },
        })
        project.registerExplicitId('test_table', 'test', '12345')

        const index = project.addFile({
            path: 'src/fluent/index.now.ts',
            content: `import { Record } from '@servicenow/sdk/core'

Record({
  table: 'test',
  $id: '1a8169a294de42f4b26920ce309c1bb6',
  data: {
      script_test: script\`console.log("test")\`,
  },
})`,
        })

        const xmlContent = await fs.readFile(path.join(__dirname, 'literal-escape-test.xml'), 'utf-8')

        await project.transform({
            path: 'changes.xml',
            content: xmlContent,
        })

        const records = await index.getRecords()
        expect(records.query()).toHaveLength(1)

        const record = records.get('test', '1a8169a294de42f4b26920ce309c1bb6')
        expect(record).toBeDefined()

        expect(record.get('script_test').getValue()).toBe(`const sinc = require(\`./src/server/s\\\`ample-class.js\`)
const myDrive = "C:\\mydrive\\sample.txt"
const foo = 'This is \`my sample st$$ri\${hi}ng'`)
    })

    test('transforms tagged template literals with escapes properly to xml', async () => {
        const project = new Project({
            packageJson: { name: 'test', version: '1.0.0' },
            config: { scope: 'x_test', scopeId: '12345' },
        })
        project.registerExplicitId('test_table', 'test', '1a8169a294de42f4b26920ce309c1bb6')

        const content = await fs.readFile(path.join(__dirname, 'tag-template-test-file.now.ts'), 'utf-8')

        project.addFile({ path: 'src/fluent/index.now.ts', content })

        const files = await project.getOutput()

        const xmlFile = files.find((f) => f.path.endsWith('test_1a8169a294de42f4b26920ce309c1bb6.xml'))

        expect(xmlFile).toBeDefined()

        const expectedXmlContent = await fs.readFile(path.join(__dirname, 'literal-escape-test.xml'), 'utf-8')

        expect(xmlFile?.content).toMatch(expectedXmlContent)
    })
})
